#include <iostream>
using namespace std;

const long long MOD = 1000000007LL;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long a, b, n, x;
    cin >> a >> b >> n >> x;

    a %= MOD;
    b %= MOD;
    x %= MOD;

    long long mul = 1, add = 0;

    while (n > 0) {
        if (n & 1) {
            add = (a * add + b) % MOD;
            mul = a * mul % MOD;
        }
        b = (a * b + b) % MOD;
        a = a * a % MOD;
        n >>= 1;
    }

    cout << (mul * x + add) % MOD;
    return 0;
}

